def max_Product(arr):
    """
    Return the pair of elements (in their original array order) whose
    product is the highest among all pairs in the array.
    """
    n = len(arr)
    if n < 2:
        return None  # No pair exists

    x, y = arr[0], arr[1]
    best = x * y
    for i in range(n):
        for j in range(i + 1, n):
            prod = arr[i] * arr[j]
            if prod > best:
                best = prod
                x, y = arr[i], arr[j]
    return (x, y)


